            if (o.t == 0 && o.i == 1) { return .one }
            if (o.t == 0 && o.i % 10 == 4) && !(o.t == 0 && o.i % 100 == 14) { return .many }
            return .other
        case 60:
            if (o.t == 0 && (o.i % 10 == 1 || o.i % 10 == 2)) && !(o.t == 0 && (o.i % 100 == 11 || o.i % 100 == 12)) { return .one }
            return .other
        case 61:
            if (o.t == 0 && (o.i % 10 == 6 || o.i % 10 == 9)) || (o.t == 0 && o.i == 10) { return .few }
            return .other
        case 62:
            if (o.t == 0 && o.i % 10 == 3) && !(o.t == 0 && o.i % 100 == 13) { return .few }
            return .other
        default:
            return .other
        }
    }
}
